'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { chooseDrop } from '../drop'
import { NES_PIXEL, TILE_WIDTH, TILE_HEIGHT, SOUND_BOSS_HIT, SOUND_ENNEMY_DIE } from '../../constant'
import { Enemy, STATE_SPAWNING, STATE_DYING, DEATH_FRAME_STEPS, drawImage, randomInt } from './common'
import { Fireball } from './projectile'

// Aquamentus, the boss of level 1 (object $3D, bank 4 $9786), read in the ROM and measured in its room $35:
// - it appears at x = $B0, y = $80 in a cloud of 13 frames (nothing the first one, then two images of 6);
// - it goes a NES pixel every 8 frames, 7 to 15 steps one way (east or west, at random), then picks again, between
//   x = $88 and $C7;
// - its timer ($28) starts again at $70 to $FF frames each time it is out: then 3 fireballs leave its mouth (x + 4),
//   aimed at Link, the first one going straight, the others drifting a NES pixel every other frame, down and up;
//   its mouth is open the last 32 frames before;
// - its legs change every 16 frames;
// - a hit takes what the weapon does from its life ($60: 6 wooden sword hits) with no knockback; it flashes 32
//   frames (sprite palettes 3, 0, 1, 2, two frames each), when nothing hurts it, and the sample $02 sounds;
// - touching it takes a heart from Link: when Link is from 8 NES pixels left of it to 15 right, 8 above to 7 below;
// - it dies as the other enemies, and leaves an item as they do (class 3).
const AQUAMENTUS = { life: 6, contactDamage: 1 }
export const AQUAMENTUS_PLACE = { x: 0xb0, y: 0x80 - 0x40 }
const SPAWN_STEPS = 13
const STEP_FRAMES = 8
const LEFT = 0x88
const RIGHT = 0xc8
const MIN_STEPS = 7
const SHOT_MIN = 0x70
const OPEN_MOUTH = 0x20
const FIRST_SHOT = 6
const MOUTH_X = 4
const DRIFTS = [0, 1, -1]
// Its fireballs stay 18 frames where they were spat, that one counted (measured: they leave the 18th after)
const FIREBALL_WAIT = 18
const LEG_FRAMES = 16
const FLASH_FRAMES = 32
const FLASH_PALETTES = ['boss', 'link', 'blue', 'red']
const CONTACT = { left: -8, right: 15, top: -8, bottom: 7 }
// What the weapons hit (NES pixels from its place), as measured with the flying sword: Link from 8 left of it to
// 15 right, or 8 above to 15 below
const HIT_BOX = { x: 3, y: 3, width: 17, height: 17 }

export class Aquamentus extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, AQUAMENTUS, random)
    this.width = 24 * NES_PIXEL
    this.height = 32 * NES_PIXEL
    this.way = 0
    this.stepsLeft = 0
    this.timer = FIRST_SHOT
    this.flash = 0
    this.frames = 0
  }

  get isVulnerable () {
    return this.isActive && this.flash === 0
  }

  getBox () {
    return { x: this.x + HIT_BOX.x * NES_PIXEL, y: this.y + HIT_BOX.y * NES_PIXEL, width: HIT_BOX.width * NES_PIXEL, height: HIT_BOX.height * NES_PIXEL }
  }

  // Link touches it (his place from its place, in NES pixels)
  touches (link) {
    const dx = (link.x - this.x) / NES_PIXEL
    const dy = (link.y - this.y) / NES_PIXEL
    return dx >= CONTACT.left && dx <= CONTACT.right && dy >= CONTACT.top && dy <= CONTACT.bottom
  }

  start (map) {
    this.setState('moving')
  }

  // No knockback: it flashes, and goes on meanwhile
  hit (link, { damage, byBomb } = {}) {
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    this.flash = FLASH_FRAMES
    soundManager.play(resource.getSound(SOUND_BOSS_HIT))
    if (this.life <= 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      this.drop = chooseDrop(this.type, link.killRecord, this.random, byBomb, this.slot)
      this.setState(STATE_DYING)
    }
  }

  process (map, link) {
    this.frames++
    if (this.flash > 0) {
      this.flash--
    }
    if (this.state === STATE_SPAWNING) {
      this.steps++
      if (this.steps >= SPAWN_STEPS) {
        this.start(map)
      }
      return
    }
    super.process(map, link)
  }

  act (map, link) {
    this.move(map)
    this.shoot(map, link)
  }

  move (map) {
    if (this.stepsLeft === 0) {
      this.way = this.random() < 0.5 ? 1 : -1
      this.stepsLeft = randomInt(this.random, 0, 15) | MIN_STEPS
      return
    }
    if (this.frames % STEP_FRAMES !== 0) {
      return
    }
    const x = (this.x - map.x) / NES_PIXEL
    if (x < LEFT) {
      this.x = map.x + LEFT * NES_PIXEL
      this.way = 1
      this.stepsLeft = MIN_STEPS
    } else if (x >= RIGHT) {
      this.x = map.x + (RIGHT - 1) * NES_PIXEL
      this.way = -1
      this.stepsLeft = MIN_STEPS
    }
    this.x += this.way * NES_PIXEL
    this.stepsLeft--
  }

  shoot (map, link) {
    if (this.timer > 0) {
      this.timer--
      return
    }
    this.timer = randomInt(this.random, 0, 0xff) | SHOT_MIN
    // They drift while it lives and moves (its routine does it)
    for (const drift of DRIFTS) {
      map.projectiles.push(new Fireball(this.x + MOUTH_X * NES_PIXEL, this.y, link, { drift, owner: this, wait: FIREBALL_WAIT }))
    }
  }

  fight (map, link) {
    const swordBox = link.getSwordBox()
    if (swordBox && this.isVulnerable && link.swordSwing !== this.lastSwing && overlaps(swordBox, this.getBox())) {
      this.hit(link)
      return
    }
    if (this.isActive && !map.frozen && this.touches(link)) {
      link.hurt(this.contactDamage, this.getBox())
    }
  }

  // Its cloud and its death are those of a tile sized enemy, at its place
  draw (context) {
    switch (this.state) {
      case STATE_SPAWNING:
        if (this.steps >= 1) {
          drawImage(context, resource.getSprite('misc_bomb_blow'), this.steps <= 6 ? 0 : 1, this.x, this.y, TILE_WIDTH, TILE_HEIGHT)
        }
        return
      case STATE_DYING:
        drawImage(context, resource.getSprite('death'), Math.floor(this.steps / DEATH_FRAME_STEPS), this.x, this.y, TILE_WIDTH, TILE_HEIGHT)
        return
    }
    super.draw(context)
  }

  drawBody (context) {
    const palette = this.flash > 0 ? FLASH_PALETTES[(Math.ceil(this.flash / 2) + 1) % 4] : FLASH_PALETTES[0]
    const mouth = this.timer < OPEN_MOUTH ? 'open' : 'move'
    drawImage(context, resource.getSprite(`aquamentus_${mouth}_${palette}`), Math.floor(this.frames / LEG_FRAMES) % 2, this.x, this.y, this.width, this.height)
  }
}
